const input = $('When Executed by Another Workflow').first().json ?? {};

const query = String(input.query ?? '').trim();
const destinationInput = String(input.destination ?? '').trim();
const journeyStage = String(input.journey_stage ?? '').trim();
const customerStatus = String(input.customer_status ?? '').trim();

const isFirstMessage =
  input.is_first_message === true ||
  String(input.is_first_message ?? '').toLowerCase() === 'true';

/*
 * Remove valores monetários que possam existir em registros
 * de passeios, políticas ou outros domínios.
 *
 * Horários, altitudes, distâncias, idades e percentuais
 * continuam preservados.
 */
function sanitizeMoneyText(value) {
  return String(value ?? '')
    .replace(
      /(?:R\$|US\$)\s*\d[\d.\s]*(?:,\d{1,2})?/gi,
      '[valor confirmado pela equipe]'
    )
    .replace(
      /\b(?:USD|BRL|CLP)\s*\d[\d.,]*/gi,
      '[valor confirmado pela equipe]'
    )
    .replace(
      /\$\s*\d[\d.,]*/g,
      '[valor confirmado pela equipe]'
    )
    .replace(
      /\b\d[\d.\s]*(?:,\d{1,2})?\s*(?:CLP|USD|BRL|pesos?\s+chilenos?|d[oó]lares?|reais)\b/gi,
      '[valor confirmado pela equipe]'
    );
}

function sanitizeRecord(record) {
  return {
    ...record,
    content: sanitizeMoneyText(record.content)
  };
}

/*
 * Primeira barreira contra preços:
 *
 * - somente registros ativos e validados;
 * - nenhum registro do domínio prices;
 * - nenhum índice de preços;
 * - sanitização de valores monetários residuais.
 */
const records = items
  .map(item => item.json)
  .filter(record =>
    record.validation_status === 'validado' &&
    record.active === true &&
    record.domain !== 'prices' &&
    record.record_key !== 'idx_prices'
  )
  .map(sanitizeRecord);

function normalize(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDestination(value) {
  const normalized = normalize(value);

  if (
    normalized.includes('uyuni') ||
    normalized.includes('salar de uyuni') ||
    normalized === 'bolivia'
  ) {
    return 'Uyuni';
  }

  if (normalized.includes('santiago')) {
    return 'Santiago';
  }

  if (
    normalized.includes('atacama') ||
    normalized.includes('san pedro')
  ) {
    return 'Atacama';
  }

  return '';
}

function containsAny(text, expressions) {
  return expressions.some(expression =>
    text.includes(normalize(expression))
  );
}

function unique(values) {
  return [...new Set(values)];
}

const normalizedQuery = normalize(query);
const normalizedJourneyStage = normalize(journeyStage);
const normalizedCustomerStatus = normalize(customerStatus);

const stopwords = new Set([
  'a',
  'o',
  'as',
  'os',
  'um',
  'uma',
  'uns',
  'umas',
  'de',
  'da',
  'do',
  'das',
  'dos',
  'em',
  'no',
  'na',
  'nos',
  'nas',
  'para',
  'por',
  'com',
  'sem',
  'e',
  'ou',
  'que',
  'qual',
  'quais',
  'como',
  'quando',
  'onde',
  'quanto',
  'quantos',
  'quantas',
  'me',
  'eu',
  'voce',
  'voces',
  'ele',
  'ela',
  'eles',
  'minha',
  'meu',
  'nosso',
  'nossa',
  'seu',
  'sua',
  'tem',
  'ter',
  'ser',
  'esta',
  'estou',
  'quero',
  'queria',
  'gostaria',
  'pode',
  'podem',
  'pra',
  'pro',
  'ao',
  'aos',
  'del',
  'el',
  'la',
  'los',
  'las',
  'al'
]);

const queryTerms = unique(
  normalizedQuery
    .split(' ')
    .filter(term =>
      term.length >= 3 &&
      !stopwords.has(term)
    )
);

const destination =
  normalizeDestination(destinationInput) ||
  normalizeDestination(query);

/*
 * Detecta pedido de preço, mas nunca pesquisa nem retorna preços.
 */
const priceRequested = containsAny(
  normalizedQuery,
  [
    'preço',
    'preco',
    'valor',
    'quanto custa',
    'quanto fica',
    'qual o valor',
    'custa',
    'orçamento',
    'orcamento',
    'cotação',
    'cotacao',
    'clp',
    'usd',
    'dólar',
    'dolar',
    'reais'
  ]
);

const indexes = records.filter(
  record => record.record_type === 'index'
);

const selectedIndexes = new Map();

function selectIndex(indexKey, reason, score = 100) {
  const existing = selectedIndexes.get(indexKey);

  if (!existing || score > existing.score) {
    selectedIndexes.set(indexKey, {
      index_key: indexKey,
      reason,
      score
    });
  }
}

/*
 * Índices obrigatórios.
 */
const mandatoryIndexKeys = [
  'idx_communication',
  'idx_brand',
  'idx_conversion',
  'idx_sales_operation'
];

for (const indexKey of mandatoryIndexKeys) {
  selectIndex(
    indexKey,
    'regra obrigatória',
    1000
  );
}

/*
 * Primeira interação.
 */
if (isFirstMessage) {
  selectIndex(
    'idx_onboarding',
    'primeira mensagem do contato',
    1000
  );
}

/*
 * Jornada do cliente.
 */
if (
  normalizedJourneyStage &&
  ![
    'unknown',
    'desconhecido'
  ].includes(normalizedJourneyStage)
) {
  selectIndex(
    'idx_journey',
    `etapa da jornada: ${journeyStage}`,
    500
  );
}

const existingCustomerStatuses = [
  'client',
  'cliente',
  'travelling',
  'viajando',
  'former client',
  'ex cliente'
];

if (
  [
    'pre trip',
    'pre viagem'
  ].includes(normalizedJourneyStage) ||
  existingCustomerStatuses.includes(normalizedCustomerStatus)
) {
  selectIndex(
    'idx_pretrip',
    'cliente existente ou em pré-viagem',
    900
  );
}

/*
 * Destino identificado.
 */
if (destination) {
  selectIndex(
    'idx_destinations',
    `destino identificado: ${destination}`,
    600
  );
}

/*
 * Regras semânticas explícitas.
 *
 * Não existe gatilho para idx_prices.
 */
const indexTriggers = [
  {
    key: 'idx_tours',
    expressions: [
      'passeio',
      'passeios',
      'tour',
      'tours',
      'geisers',
      'geysers',
      'tatio',
      'laguna',
      'lagunas',
      'valle',
      'termas',
      'vulcão',
      'vulcao',
      'trekking',
      'bike',
      'cavalgada',
      'embalse',
      'farellones',
      'portillo',
      'vinícola',
      'vinicola',
      'uyuni'
    ],
    reason: 'pergunta sobre passeio',
    score: 850
  },
  {
    key: 'idx_modalities',
    expressions: [
      'privado',
      'privativa',
      'privativo',
      'semi privado',
      'semiprivado',
      'regular',
      'exclusivo',
      'exclusiva',
      'vip',
      'personalizado',
      'personalizada',
      'grupo fechado'
    ],
    reason: 'modalidade de serviço',
    score: 900
  },
  {
    key: 'idx_handoff',
    expressions: [
      'privado',
      'privativa',
      'privativo',
      'exclusivo',
      'exclusiva',
      'vip',
      'personalizado',
      'personalizada',
      'grupo fechado',
      'atendente',
      'humano',
      'falar com alguem',
      'falar com alguém',
      'problema',
      'urgente',
      'reclamação',
      'reclamacao',
      'alteração',
      'alteracao',
      'cancelamento'
    ],
    reason: 'possível encaminhamento humano',
    score: 950
  },
  {
    key: 'idx_health',
    expressions: [
      'criança',
      'crianca',
      'menor',
      'idade',
      'filho',
      'filha',
      'bebê',
      'bebe',
      'gestante',
      'grávida',
      'gravida',
      'cardíaco',
      'cardiaco',
      'respiratório',
      'respiratorio',
      'hipertensão',
      'hipertensao',
      'altitude',
      'aclimatação',
      'aclimatacao',
      'saúde',
      'saude'
    ],
    reason: 'saúde, idade ou altitude',
    score: 900
  },
  {
    key: 'idx_date_blocks',
    expressions: [
      'natal',
      'ano novo',
      'réveillon',
      'reveillon',
      'feriado',
      'bloqueio',
      'disponibilidade',
      'disponível',
      'disponivel',
      'tem vaga',
      'funciona',
      'opera nessa data'
    ],
    reason: 'data ou disponibilidade',
    score: 900
  },
  {
    key: 'idx_policies',
    expressions: [
      'cancelamento',
      'cancelar',
      'reembolso',
      'pix',
      'cartão',
      'cartao',
      'parcela',
      'pagamento',
      'seguro',
      'drone',
      'entrada de 30',
      'saldo'
    ],
    reason: 'política comercial',
    score: 850
  },
  {
    key: 'idx_pretrip',
    expressions: [
      'já comprei',
      'ja comprei',
      'minha viagem',
      'meu embarque',
      'embarque',
      'bagagem',
      'mala',
      'roupa',
      'o que levar',
      'documento',
      'horário de busca',
      'horario de busca',
      'ponto de encontro',
      'já sou cliente',
      'ja sou cliente'
    ],
    reason: 'assunto de pré-viagem',
    score: 900
  },
  {
    key: 'idx_faq',
    expressions: [
      'transfer',
      'traslado',
      'hospedagem',
      'hotel',
      'hostel',
      'chip',
      'internet',
      'melhor época',
      'melhor epoca',
      'como chegar',
      'guia',
      'fala português',
      'fala portugues',
      'uber',
      'didi'
    ],
    reason: 'pergunta frequente',
    score: 800
  },
  {
    key: 'idx_company',
    expressions: [
      'quem vocês são',
      'quem voces sao',
      'empresa',
      'agência',
      'agencia',
      'site',
      'instagram',
      'contato',
      'whatsapp',
      'vocês trabalham',
      'voces trabalham'
    ],
    reason: 'informação sobre a empresa',
    score: 800
  }
];

for (const trigger of indexTriggers) {
  if (
    containsAny(
      normalizedQuery,
      trigger.expressions
    )
  ) {
    selectIndex(
      trigger.key,
      trigger.reason,
      trigger.score
    );
  }
}

/*
 * Regras compostas.
 */
const privateRequested = containsAny(
  normalizedQuery,
  [
    'privado',
    'privativa',
    'privativo',
    'exclusivo',
    'exclusiva',
    'vip',
    'personalizado',
    'personalizada',
    'grupo fechado'
  ]
);

if (privateRequested) {
  selectIndex(
    'idx_modalities',
    'serviço privado solicitado',
    1200
  );

  selectIndex(
    'idx_handoff',
    'privado exige encaminhamento imediato',
    1200
  );
}

const childMentioned = containsAny(
  normalizedQuery,
  [
    'criança',
    'crianca',
    'filho',
    'filha',
    'menor',
    'bebê',
    'bebe',
    'anos'
  ]
);

const ageMatch = normalizedQuery.match(
  /\b(\d{1,2})\s*anos?\b/
);

const childAge = ageMatch
  ? Number(ageMatch[1])
  : null;

const uyuniMentioned =
  destination === 'Uyuni' ||
  containsAny(
    normalizedQuery,
    [
      'uyuni',
      'salar de uyuni',
      'bolivia'
    ]
  );

if (
  childMentioned &&
  uyuniMentioned
) {
  selectIndex(
    'idx_health',
    'Uyuni com criança',
    1300
  );

  selectIndex(
    'idx_handoff',
    'Uyuni com criança exige avaliação',
    1300
  );

  selectIndex(
    'idx_tours',
    'informações da expedição Uyuni',
    900
  );
}

/*
 * Pontuação semântica dos índices.
 */
for (const index of indexes) {
  const title = normalize(index.title);
  const content = normalize(index.content);
  const keywords = normalize(index.keywords);
  const domain = normalize(index.domain);

  let score = 0;
  const matchedTerms = [];

  for (const term of queryTerms) {
    let matched = false;

    if (domain.includes(term)) {
      score += 14;
      matched = true;
    }

    if (title.includes(term)) {
      score += 10;
      matched = true;
    }

    if (keywords.includes(term)) {
      score += 8;
      matched = true;
    }

    if (content.includes(term)) {
      score += 3;
      matched = true;
    }

    if (matched) {
      matchedTerms.push(term);
    }
  }

  if (score > 0) {
    selectIndex(
      index.record_key,
      `termos relacionados: ${unique(matchedTerms).join(', ')}`,
      score
    );
  }
}

const selectedIndexKeys = [
  ...selectedIndexes.keys()
];

/*
 * Regras essenciais que entram em todas as consultas.
 */
const mandatoryRecordKeys = [
  'style_whatsapp',
  'style_one_question',
  'style_emoji',
  'style_natural',
  'style_no_empty',
  'style_no_markdown',
  'style_name',
  'style_transparency',
  'sales_progressive_collection',
  'sales_email_optional',
  'sales_manager_all_fields',
  'brand_value_question',
  'conversion_reduce_effort',
  'conversion_context'
];

const mandatoryRecords = records
  .filter(record =>
    mandatoryRecordKeys.includes(
      record.record_key
    )
  )
  .sort((a, b) =>
    Number(b.priority ?? 0) -
    Number(a.priority ?? 0)
  );

function recordMatchesDestination(record) {
  const recordDestination = normalizeDestination(
    record.destination
  );

  if (!destination) {
    return true;
  }

  if (
    !recordDestination ||
    normalize(record.destination) === 'geral'
  ) {
    return true;
  }

  return recordDestination === destination;
}

function scoreRecord(record) {
  const title = normalize(record.title);
  const content = normalize(record.content);
  const keywords = normalize(record.keywords);
  const topic = normalize(record.topic);
  const recordKey = normalize(record.record_key);

  let score =
    Number(record.priority ?? 0) / 10;

  const matchedTerms = [];

  for (const term of queryTerms) {
    let matched = false;

    if (recordKey.includes(term)) {
      score += 12;
      matched = true;
    }

    if (title.includes(term)) {
      score += 10;
      matched = true;
    }

    if (keywords.includes(term)) {
      score += 8;
      matched = true;
    }

    if (topic.includes(term)) {
      score += 5;
      matched = true;
    }

    const occurrences =
      content.split(term).length - 1;

    if (occurrences > 0) {
      score +=
        Math.min(occurrences, 4) * 3;

      matched = true;
    }

    if (matched) {
      matchedTerms.push(term);
    }
  }

  if (destination) {
    const recordDestination =
      normalizeDestination(record.destination);

    if (
      recordDestination === destination
    ) {
      score += 20;
    }

    if (
      normalize(record.destination) === 'geral'
    ) {
      score += 3;
    }
  }

  if (
    normalizedJourneyStage &&
    normalize(record.journey_stage) ===
      normalizedJourneyStage
  ) {
    score += 20;
  }

  if (
    normalize(record.journey_stage) === 'all'
  ) {
    score += 2;
  }

  if (
    privateRequested &&
    record.record_key === 'handoff_private'
  ) {
    score += 100;
  }

  if (
    childMentioned &&
    uyuniMentioned &&
    [
      'handoff_uyuni_child',
      'health_uyuni_child_no_denial'
    ].includes(record.record_key)
  ) {
    score += 120;
  }

  if (
    isFirstMessage &&
    record.parent_key === 'idx_onboarding'
  ) {
    score += 100;
  }

  return {
    ...record,
    retrieval_score: score,
    matched_terms: unique(matchedTerms)
  };
}

const situationalIndexKeys =
  selectedIndexKeys.filter(
    key => !mandatoryIndexKeys.includes(key)
  );

const limitsByIndex = {
  idx_onboarding: 5,
  idx_journey: 6,
  idx_company: 5,
  idx_destinations: 4,
  idx_modalities: 6,
  idx_tours: 6,
  idx_policies: 6,
  idx_health: 6,
  idx_date_blocks: 5,
  idx_handoff: 8,
  idx_pretrip: 8,
  idx_faq: 6
};

const situationalRecords = [];

for (const indexKey of situationalIndexKeys) {
  const candidates = records
    .filter(record =>
      record.parent_key === indexKey &&
      record.record_type !== 'index' &&
      recordMatchesDestination(record)
    )
    .filter(record => {
      /*
       * Pedido privado de Uyuni não precisa
       * trazer a modalidade regular.
       */
      if (
        privateRequested &&
        record.record_key ===
          'tour_uyuni_regular'
      ) {
        return false;
      }

      /*
       * Criança com 7 anos ou mais não deve
       * receber a regra exclusiva para menores
       * de 7 anos.
       */
      if (
        childAge !== null &&
        childAge >= 7 &&
        record.record_key ===
          'health_under7_altitude'
      ) {
        return false;
      }

      return true;
    })
    .map(scoreRecord)
    .sort((a, b) =>
      b.retrieval_score -
      a.retrieval_score
    );

  const limit =
    limitsByIndex[indexKey] ?? 5;

  const relevant = candidates.filter(
    record =>
      record.retrieval_score >= 20 ||
      indexKey === 'idx_onboarding' ||
      (
        indexKey === 'idx_pretrip' &&
        [
          'pre trip',
          'pre viagem'
        ].includes(normalizedJourneyStage)
      )
  );

  const selected =
    (
      relevant.length > 0
        ? relevant
        : candidates.slice(0, 1)
    ).slice(0, limit);

  situationalRecords.push(...selected);
}

/*
 * Remove duplicidades.
 */
const mandatoryKeys = new Set(
  mandatoryRecords.map(
    record => record.record_key
  )
);

const relevantRecords = situationalRecords
  .filter(record =>
    !mandatoryKeys.has(record.record_key)
  )
  .filter(
    (record, index, array) =>
      array.findIndex(
        item =>
          item.record_key ===
          record.record_key
      ) === index
  );

/*
 * Detalhes dos índices selecionados.
 */
const selectedIndexDetails =
  selectedIndexKeys
    .map(indexKey => {
      const index = indexes.find(
        item =>
          item.record_key === indexKey
      );

      const selection =
        selectedIndexes.get(indexKey);

      return {
        index_key: indexKey,
        domain: index?.domain ?? '',
        title: index?.title ?? indexKey,
        reason: selection?.reason ?? '',
        score: selection?.score ?? 0
      };
    })
    .filter(index =>
      index.index_key !== 'idx_prices'
    )
    .sort((a, b) =>
      b.score - a.score
    );

function formatRecord(record, number) {
  const lines = [
    `[REGISTRO ${number}]`,
    `Chave: ${record.record_key}`,
    `Domínio: ${record.domain}`,
    `Título: ${record.title}`,
    `Conteúdo: ${record.content}`
  ];

  if (record.destination) {
    lines.push(
      `Destino: ${record.destination}`
    );
  }

  if (record.journey_stage) {
    lines.push(
      `Etapa: ${record.journey_stage}`
    );
  }

  if (record.handoff_reason) {
    lines.push(
      `Motivo de encaminhamento: ${record.handoff_reason}`
    );
  }

  return lines.join('\n');
}

const mandatoryContext = mandatoryRecords
  .map((record, index) =>
    formatRecord(record, index + 1)
  )
  .join('\n\n');

const relevantContext = relevantRecords
  .map((record, index) =>
    formatRecord(record, index + 1)
  )
  .join('\n\n');

/*
 * Segunda barreira explícita contra divulgação de preços.
 * Esta instrução sempre é devolvida para o agente.
 */
const priceRestrictionContext = [
  '=== REGRA ABSOLUTA — PREÇOS ===',
  'Nunca informe preços, valores, estimativas, faixas de preço ou cálculos ao cliente.',
  'Ignore qualquer valor monetário presente no histórico ou em outra fonte.',
  'Quando houver pergunta sobre preço, explique que os valores são confirmados pela equipe conforme o roteiro e a modalidade.',
  'Continue a coleta de uma informação necessária por vez e encaminhe para cotação humana quando aplicável.'
].join('\n');

const context = [
  priceRestrictionContext,
  '',
  '=== REGRAS OBRIGATÓRIAS ===',
  mandatoryContext ||
    'Nenhuma regra obrigatória encontrada.',
  '',
  '=== CONTEXTO RELEVANTE ===',
  relevantContext ||
    'Nenhum contexto situacional encontrado.'
].join('\n');

return [
  {
    json: {
      found:
        mandatoryRecords.length > 0 ||
        relevantRecords.length > 0,

      query,
      destination,
      journey_stage: journeyStage,
      customer_status: customerStatus,
      is_first_message: isFirstMessage,

      price_requested: priceRequested,
      price_disclosure_blocked: true,

      private_requested: privateRequested,
      child_mentioned: childMentioned,
      child_age: childAge,
      uyuni_mentioned: uyuniMentioned,

      selected_indexes:
        selectedIndexDetails,

      mandatory_rules_count:
        mandatoryRecords.length,

      relevant_records_count:
        relevantRecords.length,

      mandatory_rules:
        mandatoryRecords,

      relevant_records:
        relevantRecords,

      context
    }
  }
];
